package keystrokesmod.script.packet.clientbound;
import keystrokesmod.script.model.Vec3; import net.minecraft.network.play.server.S2APacketParticles;
public class S2A extends SPacket { public String type; public Vec3 position,offset; public float speed; public int count; public boolean longDistance; public int[] args; public S2A(S2APacketParticles value){super(value);type=value.getParticleType().name();position=new Vec3(value.getXCoordinate(),value.getYCoordinate(),value.getZCoordinate());offset=new Vec3(value.getXOffset(),value.getYOffset(),value.getZOffset());speed=value.getParticleSpeed();count=value.getParticleCount();longDistance=value.isLongDistance();args=value.getParticleArgs();} public S2A(String type,boolean distance,Vec3 pos,Vec3 offset,float speed,int count,int[] args){super(null);this.type=type;longDistance=distance;position=pos;this.offset=offset;this.speed=speed;this.count=count;this.args=args;} }
